const STOP_MARKERS = [
  'Für Sie empfohlen',
  'Neueste Artikel',
  'Artikel von NZZ Bellevue',
  'Kostenlose Onlinespiele',
];

const SKIP_HEADINGS = new Set([
  'optimieren sie ihre browsereinstellungen',
]);

const SKIP_PARAGRAPH_STARTS = [
  'teilen',
  'merken',
  'nzz.ch benötigt javascript',
  'bitte passen sie die einstellungen an',
  'mit dem premium-newsletter',
];

const html = $input.first().json.data;
if (!html) {
  throw new Error('Empty response from nzz.ch/briefing');
}

function decodeEntities(text) {
  return text
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCharCode(parseInt(n, 16)));
}

function stripTags(fragment) {
  return decodeEntities(
    fragment
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<[^>]+>/g, '')
      .replace(/\s+/g, ' ')
      .trim(),
  );
}

function escapeHtml(text) {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

const start = html.search(/<h1\b/i);
if (start < 0) {
  throw new Error('Briefing H1 not found');
}

let stop = html.length;
for (const marker of STOP_MARKERS) {
  const idx = html.indexOf(marker, start);
  if (idx >= 0) stop = Math.min(stop, idx);
}
const chunk = html.slice(start, stop);

const blocks = [];
const tagRe = /<(h[1-3]|p|ul)\b([^>]*)>([\s\S]*?)<\/\1>/gi;
let match;
while ((match = tagRe.exec(chunk)) !== null) {
  const tag = match[1].toLowerCase();
  const inner = match[3];

  if (tag === 'ul') {
    const items = [];
    const liRe = /<li\b[^>]*>([\s\S]*?)<\/li>/gi;
    let li;
    while ((li = liRe.exec(inner)) !== null) {
      const text = stripTags(li[1]);
      if (text) items.push(text);
    }
    if (items.length) blocks.push({ tag: 'ul', items });
    continue;
  }

  const text = stripTags(inner);
  if (!text) continue;
  const low = text.toLowerCase();
  if (tag.startsWith('h') && SKIP_HEADINGS.has(low)) continue;
  if (tag === 'p' && SKIP_PARAGRAPH_STARTS.some((p) => low === p || low.startsWith(p))) continue;
  blocks.push({ tag, text });
}

if (!blocks.length) {
  throw new Error('No briefing content extracted');
}

const title = blocks.find((b) => b.tag === 'h1')?.text ?? 'NZZ Briefing';
const stamp = new Date().toLocaleString('sv-SE', { timeZone: 'Europe/Berlin' }).slice(0, 10);
const filename = `nzz-briefing-${stamp}.pdf`;

const bodyHtml = blocks
  .map((block) => {
    if (block.tag === 'ul') {
      const lis = block.items.map((item) => `<li>${escapeHtml(item)}</li>`).join('');
      return `<ul>${lis}</ul>`;
    }
    const t = escapeHtml(block.text);
    if (block.tag === 'h1') return `<h1>${t}</h1>`;
    if (block.tag === 'h2') return `<h2>${t}</h2>`;
    if (block.tag === 'h3') return `<h3>${t}</h3>`;
    return `<p>${t}</p>`;
  })
  .join('\n');

const documentHtml = `<!DOCTYPE html>
<html lang="de">
<head>
  <meta charset="utf-8" />
  <title>${escapeHtml(title)}</title>
  <style>
    @page { margin: 14mm; }
    body {
      margin: 0;
      color: #111;
      font-family: Georgia, "Times New Roman", serif;
      font-size: 12.5pt;
      line-height: 1.45;
    }
    h1 {
      font-size: 22pt;
      line-height: 1.2;
      margin: 0 0 0.4em;
    }
    h2 {
      font-size: 14.5pt;
      line-height: 1.25;
      margin: 1.35em 0 0.45em;
      padding-top: 0.2em;
      border-top: 1px solid #bbb;
    }
    h2:first-of-type { border-top: 0; padding-top: 0; }
    h3 { font-size: 12.5pt; margin: 1em 0 0.35em; }
    p { margin: 0 0 0.75em; }
    ul { margin: 0 0 1em; padding-left: 1.2em; }
    li { margin: 0 0 0.55em; }
    .meta {
      font-family: sans-serif;
      font-size: 9.5pt;
      color: #444;
      margin: 0 0 1.4em;
    }
  </style>
</head>
<body>
  <p class="meta">NZZ Briefing · ${escapeHtml(stamp)} · nzz.ch/briefing</p>
  ${bodyHtml}
</body>
</html>`;

const binary = await this.helpers.prepareBinaryData(
  Buffer.from(documentHtml, 'utf8'),
  'index.html',
  'text/html',
);

return [
  {
    json: { title, filename },
    binary: { data: binary },
  },
];

const meta = $('Build reMarkable HTML').first().json;
const item = $input.first();

item.json = {
  ...item.json,
  title: meta.title,
  filename: meta.filename,
};

if (item.binary?.data) {
  item.binary.data.fileName = meta.filename;
  item.binary.data.mimeType = 'application/pdf';
}

return [item];
